function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function nav(v){document.querySelectorAll('.view').forEach(e=>e.classList.toggle('active',e.id===v));document.querySelectorAll('.nav button').forEach(e=>e.classList.toggle('active',e.dataset.view===v));window.scrollTo(0,0);if(v==='plot')renderPlot()}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>nav(b.dataset.view));$('#toPlot').onclick=()=>nav('plot');
function parseDelimited(text,sep){let out=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(c===sep&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);out.push(row);row=[];cell=''}else cell+=c}row.push(cell);out.push(row);return out}
function parsedMatrix(text){text=String(text||'').replace(/\u00a0/g,' ').trim();if(!text)throw Error('请粘贴内容');let matrix;if(/<table[\s>]/i.test(text)){let doc=new DOMParser().parseFromString(text,'text/html'),table=doc.querySelector('table');if(!table)throw Error('未找到表格');matrix=[...table.rows].map(tr=>[...tr.cells].map(td=>td.textContent.trim()))}else{let first=text.split(/\r?\n/)[0],sep=['\t',',',';'].sort((a,b)=>first.split(b).length-first.split(a).length)[0];matrix=parseDelimited(text,sep)}matrix=matrix.map(row=>row.map(v=>String(v??'').trim())).filter(row=>row.some(Boolean));let width=Math.max(0,...matrix.map(r=>r.length));let kept=Array.from({length:width},(_,i)=>i).filter(i=>matrix.some(r=>r[i]));matrix=matrix.map(row=>kept.map(i=>row[i]||''));if(matrix.length<2||matrix[0].length<2)throw Error('需要表头和至少一行数据');return matrix}
function normalizeMatrix(matrix){let headers=matrix[0],body=matrix.slice(1),norm=new Set([...DEFAULT_ORDER.map(x=>x.toLowerCase()),...Object.keys(ELEMENT_ALIASES)]),colHits=headers.slice(1).filter(v=>norm.has(v.toLowerCase())).length,rowHits=body.filter(r=>norm.has((r[0]||'').toLowerCase())).length,transposed=rowHits>colHits;if(transposed){matrix=[['SampleID',...body.map(r=>r[0])],...headers.slice(1).map((h,i)=>[h,...body.map(r=>r[i+1]||'')])];headers=matrix[0];body=matrix.slice(1)}headers=[headers[0].trim(),...headers.slice(1).map(canonical)];let seen=new Map(),warnings=[];headers=headers.map(h=>{let n=(seen.get(h)||0)+1;seen.set(h,n);if(n>1){warnings.push(`重复列 ${h} 已标为 ${h} (${n})`);return `${h} (${n})`}return h});return {headers,body,orientation:transposed?`自动转置：行匹配 ${rowHits} > 列匹配 ${colHits}`:`无需转置：列匹配 ${colHits}`,warnings}}
function parse(){let result;try{result=normalizeMatrix(parsedMatrix($('#source').value))}catch(e){$('#parseStatus').textContent=e.message;return}cols=result.headers;original=cols.slice();sampleCol=cols.find(c=>/^(sample|sample.?id|样品|样品编号|编号)$/i.test(c))||cols[0];groupCol=cols.find(c=>/^(group|分组|组别|类别)$/i.test(c))||'';rows=result.body.map((values,i)=>({id:i,selected:true,data:Object.fromEntries(cols.map((c,j)=>[c,values[j]??'']))}));let avail=cols.filter(c=>c!==sampleCol&&c!==groupCol);axis.x.num=avail.find(c=>/^SiO2$/i.test(c))||avail[0]||'';axis.y.num=avail.find(c=>/^MgO$/i.test(c))||avail.find(c=>c!==axis.x.num)||avail[0]||'';axis.x.den=axis.y.den='';axis.x.use=axis.y.use=false;$('#parseStatus').textContent=`解析成功 · ${result.orientation} · ${rows.length} 个样品${result.warnings.length?' · '+result.warnings.join('；'):''}`;renderAll()}
function optionMarkup(selected,blank=true){return (blank?'<option value="">留空</option>':'')+cols.map(c=>`<option value="${esc(c)}" ${c===selected?'selected':''}>${esc(c)}</option>`).join('')}
function effectiveOrder(){let present=cols.filter(c=>c!==sampleCol&&c!==groupCol),extra=present.filter(c=>!order.includes(c)).sort((a,b)=>a.localeCompare(b,undefined,{sensitivity:'base'}));return [...order,...extra].filter(c=>!excludedElements.has(c))}
function renderOrder(){
  const list=effectiveOrder(),present=new Set(cols),box=$('#order');
  $('#orderCount').textContent=`默认 ${DEFAULT_ORDER.length} 项 · 当前 ${list.length} 项`;
  box.innerHTML=list.map(c=>`<div role="listitem" tabindex="0" draggable="true" class="chip ${present.has(c)?'':'absent'}" data-col="${esc(c)}" aria-label="${esc(c)}，拖动或方向键调整顺序" title="拖动调整顺序；方向键微调"><span class="grip" aria-hidden="true">⋮⋮</span><span>${esc(c)}</span><button type="button" class="chip-remove" data-remove="${esc(c)}" aria-label="从排序中移除 ${esc(c)}" title="移除 ${esc(c)}">×</button></div>`).join('');
  box.querySelectorAll('.chip-remove').forEach(button=>button.onclick=e=>{e.stopPropagation();let col=button.dataset.remove;excludedElements.add(col);order=order.filter(c=>c!==col);$('#orderStatus').textContent=`已移除 ${col}；原始数据仍保留此列`;renderOrder();renderTables()});
  let dragged=null,touchSource=null;
  function move(source,target,after=false){let arr=effectiveOrder(),from=arr.indexOf(source),to=arr.indexOf(target);if(from<0||to<0||from===to)return;arr.splice(from,1);to=arr.indexOf(target)+(after?1:0);arr.splice(to,0,source);order=arr;$('#orderStatus').textContent=`${source} 已移到第 ${to+1} 位`;renderOrder();renderTables()}
  box.querySelectorAll('.chip').forEach(chip=>{
    chip.addEventListener('dragstart',e=>{if(e.target.closest('.chip-remove')){e.preventDefault();return}dragged=chip.dataset.col;chip.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragged)});
    chip.addEventListener('dragend',()=>{dragged=null;chip.classList.remove('dragging');box.querySelectorAll('.drag-target').forEach(x=>x.classList.remove('drag-target'))});
    chip.addEventListener('dragover',e=>{e.preventDefault();chip.classList.add('drag-target')});
    chip.addEventListener('dragleave',()=>chip.classList.remove('drag-target'));
    chip.addEventListener('drop',e=>{e.preventDefault();chip.classList.remove('drag-target');move(dragged||e.dataTransfer.getData('text/plain'),chip.dataset.col,e.clientX>chip.getBoundingClientRect().left+chip.offsetWidth/2)});
    chip.addEventListener('keydown',e=>{if(e.target!==chip||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();let arr=effectiveOrder(),i=arr.indexOf(chip.dataset.col),j=i+(e.key==='ArrowLeft'?-1:1);if(j<0||j>=arr.length)return;let target=arr[j];move(chip.dataset.col,target,e.key==='ArrowRight');[...box.querySelectorAll('.chip')].find(x=>x.dataset.col===chip.dataset.col)?.focus()});
    chip.addEventListener('pointerdown',e=>{if(e.pointerType==='touch'&&!e.target.closest('.chip-remove'))touchSource=chip.dataset.col});
    chip.addEventListener('pointerup',e=>{if(e.pointerType!=='touch'||!touchSource)return;let target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.chip');if(target)move(touchSource,target.dataset.col);touchSource=null});
  });
}
function renderAll(){let sel=$('#sampleCol'),grp=$('#groupCol');sel.innerHTML=optionMarkup(sampleCol,false);grp.innerHTML=optionMarkup(groupCol);renderOrder();renderTables();renderAxis();renderPlot()}
$('#sampleCol').onchange=e=>{sampleCol=e.target.value;if(groupCol===sampleCol)groupCol='';renderAll()};$('#groupCol').onchange=e=>{groupCol=e.target.value;if(groupCol===sampleCol)groupCol='';renderAll()};$('#resetOrder').onclick=()=>{order=DEFAULT_ORDER.slice();excludedElements.clear();$('#orderStatus').textContent='已恢复默认顺序';renderOrder();renderTables()};$('#showPresent').onchange=renderTables;$('#parse').onclick=parse;$('#example').onclick=()=>{$('#source').value=demo;parse()};
$('#clearData').onclick=()=>{$('#source').value='';rows=[];cols=[];original=[];sampleCol='';groupCol='';axis.x.num=axis.y.num='';$('#parseStatus').textContent='数据已清空';renderAll()};
function addElement(){
  const input=$('#newElement'),name=canonical(input.value.trim());
  if(!name){$('#orderStatus').textContent='请先输入元素名称';return}
  if(name===sampleCol||name===groupCol){$('#orderStatus').textContent='该名称已用作样品或分组列';return}
  if(effectiveOrder().includes(name)&&cols.includes(name)){$('#orderStatus').textContent=`${name} 已在元素列表中`;return}
  order=effectiveOrder().filter(c=>c!==name);excludedElements.delete(name);order.push(name);
  if(!cols.includes(name)){cols.push(name);rows.forEach(r=>r.data[name]='')}
  input.value='';$('#orderStatus').textContent=`${name} 已添加到末尾；可在整理后的表格中填写数值`;
  renderOrder();renderTables();renderAxis();renderPlot();
}
$('#addElement').onclick=addElement;
$('#newElement').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();addElement()}};
function group(r){return groupCol?(r.data[groupCol]||'未分组'):'全部样品'}
function plotGroup(r){return $('#groupPlot').checked?group(r):'全部样品'}
